SELECT p.gender, p.age, s.hadm_id, s.los, d.primary_diagnosis, d.secondary_diagnosis, percentile_cont(0.25) within GROUP (ORDER BY COUNT(p.subject_id)) AS p25, percentile_cont(0.50) within GROUP (ORDER BY COUNT(p.subject_id)) AS p50, percentile_cont(0.75) within GROUP (ORDER BY COUNT(p.subject_id)) AS p75 FROM patients p JOIN admissions s ON p.subject_id = s.subject_id JOIN diagnoses_icd d ON s.hadm_id = d.hadm_id WHERE p.gender = 'F' AND p.age BETWEEN 50 AND 60 AND s.admission_type = 'ACS' GROUP BY p.gender, p.age, s.hadm_id, s.los, d.primary_diagnosis, d.secondary_diagnosis ORDER BY p.gender, p.age, s.hadm_id, s.los, d.primary_diagnosis, d.secondary_diagnosis NULLS LAST;